@@ -439,0 +439,12 @@
+
+    // The state of strict static field accesses is reset in InstanceKlass::remove_unshareable_info
+    // when the class does not have an AOT initialized mirror. Since <clinit> will be called in
+    // the subsequent runtime, the resolved field entries associated with strict static fields are
+    // not archiveable.
+    if (rfi->is_resolved(Bytecodes::_getstatic) || rfi->is_resolved(Bytecodes::_putstatic)) {
+      InstanceKlass* holder = rfi->field_holder();
+      if (!holder->has_aot_initialized_mirror() && holder->field_is_strict(rfi->field_index())) {
+        archivable = false;
+      }
+    }
+

@@ -3119,0 +3119,13 @@
+  // Classes without an AOT-initialized mirror will run <clinit> again. Restore
+  // the initial status of their strict static fields for that execution.
+  if (has_strict_static_fields() && !has_aot_initialized_mirror()) {
+    for (AllFieldStream fs(this); !fs.done(); fs.next()) {
+      FieldInfo fi = fs.to_FieldInfo();
+      if (fi.access_flags().is_strict() && fi.access_flags().is_static() && fi.initializer_index() == 0) {
+        FieldStatus& fs = *fields_status()->adr_at(fi.index());
+        fs.update_strict_static_unset(true);
+        fs.update_strict_static_unread(true);
+      }
+    }
+  }
+
